 static byte[] Read(Stream source){using var result=new MemoryStream();source.CopyTo(result);return result.ToArray();}
 static FenceStyle AddSharedFence(WorldProject world){var style=new FenceStyle{Id="http-shared",W="fencing_01_40",N="fencing_01_41"};world.FenceStyles=[style];world.Fences=[new(){Id="http-shared-line",Style=style.Id,Points=[new(100*256+20,100*256+20),new(100*256+30,100*256+20)]}];return style;}
 static GameAssetCatalog FenceCatalog(string root,MapProject project,FenceStyle style){var ids=NativeScene.ResourceIds(project).Append(style.W).Append(style.N).Distinct().ToArray();var game=Path.Combine(root,"http-fence-game");Directory.CreateDirectory(Path.Combine(game,"media","texturepacks"));File.WriteAllText(Path.Combine(game,"media","newtiledefinitions.tiles.txt"),string.Join('\n',ids.Select(id=>"// "+id+"\n tile\n {\n solidfloor = \n }\n")));var assets=new GameAssetCatalog(root,game,new GameInstallationDiscovery([],false));Check(assets.Ready,"Synthetic HTTP fence catalog did not load");return assets;}
 static ExportJobStatus Wait(ExportJobStore jobs,string id){var deadline=DateTime.UtcNow.AddSeconds(60);while(DateTime.UtcNow<deadline){var state=jobs.Status(id);if(state.Status is not ("queued" or "running")){Thread.Sleep(50);return state;}Thread.Sleep(10);}throw new Exception("Streamed native job timed out");}
 static void InWorkspace(Action<string> run){var root=Path.Combine(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")??Path.GetFullPath("."),"work","section-streaming-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{run(root);}finally{Directory.Delete(root,true);}}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
}
